INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2023/06/30 12:00:00", 0, 1, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 2, 2, 10003, "2023/09/22 14:59:59", -470, "ライラエル", 126501, 1, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2023/06/30 12:00:00", 0, 1, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 1, 1, 10004, "2023/09/22 14:59:59", -470, "ライラエル", 126501, 2, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2023/09/15 15:00:00", 0, 2, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 2, 2, 10005, "2023/12/22 14:59:59", -470, "リンド", 127702, 1, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2023/09/15 15:00:00", 0, 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2, 2, 10006, "2023/12/22 14:59:59", -470, "リンド", 127702, 2, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2023/09/15 15:00:00", 0, 2, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 1, 1, 10007, "2023/12/22 14:59:59", -470, "ヴルム", 127802, 1, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2023/09/15 15:00:00", 0, 2, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 1, 2, 10008, "2023/12/22 14:59:59", -470, "ヴルム", 127802, 2, 6.5, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2023/12/15 15:00:00", 0, 3, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 1, 2, 10009, "2024/03/22 14:59:59", -470, "アネモネ", 129602, 1, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2023/12/15 15:00:00", 0, 3, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 1, 2, 10010, "2024/03/22 14:59:59", -470, "アネモネ", 129602, 2, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2023/12/15 15:00:00", 0, 3, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 1, 1, 10011, "2024/03/22 14:59:59", -470, "ネフィ=ネラ", 129701, 1, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2023/12/15 15:00:00", 0, 3, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 1, 2, 10012, "2024/03/22 14:59:59", -470, "ネフィ=ネラ", 129701, 2, 6.2, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/03/15 15:00:00", 0, 4, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 5, 3, 10013, "2024/06/22 14:59:59", -470, "カノン", 130301, 1, 3.1, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/03/15 15:00:00", 0, 4, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 2, 3, 10014, "2024/06/22 14:59:59", -470, "カノン", 130301, 2, 6.15, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/03/15 15:00:00", 0, 4, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 2, 2, 10015, "2024/06/22 14:59:59", -470, "ナーナ", 130401, 1, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/03/15 15:00:00", 0, 4, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 1, 2, 10016, "2024/06/22 14:59:59", -470, "ナーナ", 130401, 2, 3.35, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/06/15 15:00:00", 0, 5, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 1, 1, 10017, "2024/09/22 14:59:59", -470, "ホウオウ", 130502, 1, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/06/15 15:00:00", 0, 5, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 1, 2, 10018, "2024/09/22 14:59:59", -470, "ホウオウ", 130502, 2, 3.18, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/06/15 15:00:00", 0, 5, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 4, 4, 10019, "2024/09/22 14:59:59", -470, "ホウオウ", 130503, 3, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/06/15 15:00:00", 0, 5, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 2, 1, 10020, "2024/09/22 14:59:59", -470, "ネア", 123301, 1, 4.9, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/06/15 15:00:00", 0, 5, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 2, 1, 10021, "2024/09/22 14:59:59", -470, "ネア", 123301, 2, 4.8, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/09/15 15:00:00", 0, 6, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 1, 3, 10022, "2024/12/22 14:59:59", -470, "カリザ", 133301, 1, 4.922, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/09/15 15:00:00", 0, 6, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 5, 3, 10023, "2024/12/22 14:59:59", -470, "カリザ", 133301, 2, 9.638, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/09/15 15:00:00", 0, 6, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 2, 1, 10024, "2024/12/22 14:59:59", -470, "ミーア", 133401, 1, 2.88, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/09/15 15:00:00", 0, 6, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 1, 5, 10025, "2024/12/22 14:59:59", -470, "ミーア", 133401, 2, 4.818, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/12/15 15:00:00", 0, 7, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 1, 2, 10026, "2025/03/22 14:59:59", -470, "グレイス", 133002, 1, 1.78, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/12/15 15:00:00", 0, 7, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 7, 1, 10027, "2025/03/22 14:59:59", -470, "グレイス", 133002, 2, 6.15, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/12/15 15:00:00", 0, 7, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 2, 6, 10028, "2025/03/22 14:59:59", -470, "ヴァイオレット", 133102, 1, 4.28, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2024/12/15 15:00:00", 0, 7, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 1, 1, 10029, "2025/03/22 14:59:59", -470, "ヴァイオレット", 133102, 2, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/03/15 15:00:00", 0, 8, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 1, 2, 10030, "2025/06/23 14:59:59", -470, "ルルィ", 136902, 1, 5.53, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/03/15 15:00:00", 0, 8, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 7, 9, 10031, "2025/06/23 14:59:59", -470, "ルルィ", 136902, 2, 6.05, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/03/15 15:00:00", 0, 8, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 1, 2, 10032, "2025/06/23 14:59:59", -470, "デュラン", 137001, 1, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/03/15 15:00:00", 0, 8, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 1, 2, 10033, "2025/06/23 14:59:59", -470, "デュラン", 137001, 2, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/06/16 15:00:00", 0, 9, "おう\n好きなもん持ってきな", 2, 2, 10034, "2025/09/23 14:59:59", -470, "サツキ", 135902, 1, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/06/16 15:00:00", 0, 9, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 6, 1, 10035, "2025/09/23 14:59:59", -470, "サツキ", 135902, 2, 4.935, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/06/16 15:00:00", 0, 9, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 5, 2, 10036, "2025/09/23 14:59:59", -470, "ユキノ", 135802, 1, 7.441, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/06/16 15:00:00", 0, 9, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 7, 7, 10037, "2025/09/23 14:59:59", -470, "ユキノ", 135802, 2, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/09/16 15:00:00", 0, 10, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2, 2, 10038, "2025/12/22 14:59:59", -470, "クルル", 130901, 1, 2.295, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/09/16 15:00:00", 0, 10, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 6, 1, 10039, "2025/12/22 14:59:59", -470, "クルル", 130901, 2, 6.281, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/09/16 15:00:00", 0, 10, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 1, 2, 10040, "2025/12/22 14:59:59", -470, "ヴォルガーノ", 137701, 1, 5.549, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/09/16 15:00:00", 0, 10, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 6, 3, 10041, "2025/12/22 14:59:59", -470, "ヴォルガーノ", 137701, 2, 2.64, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/12/15 15:00:00", 0, 11, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 4, 7, 10042, "2026/03/23 11:59:59", -470, "ライラエル", 132801, 1, 7.642, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/12/15 15:00:00", 0, 11, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 1, 1, 10043, "2026/03/23 11:59:59", -470, "ライラエル", 132802, 2, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/12/15 15:00:00", 0, 11, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 1, 1, 10044, "2026/03/23 11:59:59", -470, "クローチェ", 134502, 1, 0, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2025/12/15 15:00:00", 0, 11, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 1, 2, 10045, "2026/03/23 11:59:59", -470, "クローチェ", 134501, 2, 3.72, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2026/03/16 12:00:00", 0, 12, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 1, 2, 10046, "2026/06/22 11:59:59", -470, "ネフィ＝ネラ", 138201, 1, 4.991, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2026/03/16 12:00:00", 0, 12, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 4, 1, 10047, "2026/06/22 11:59:59", -470, "ネフィ＝ネラ", 138201, 2, 3.877, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2026/03/16 12:00:00", 0, 12, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 6, 4, 10048, "2026/06/22 11:59:59", -470, "アラクネ", 136001, 1, 1.71, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2026/03/16 12:00:00", 0, 12, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 2, 5, 10049, "2026/06/22 11:59:59", -470, "アラクネ", 136001, 2, 5.32, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2026/06/15 12:00:00", 0, 13, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 4, 9, 10050, "2026/09/22 11:59:59", -470, "アネモネ", 135401, 1, 3.727, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2026/06/15 12:00:00", 0, 13, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 9, 7, 10051, "2026/09/22 11:59:59", -470, "アネモネ", 135401, 2, 7.213, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2026/06/15 12:00:00", 0, 13, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 2, 1, 10052, "2026/09/22 11:59:59", -470, "クリア", 135301, 1, 1.874, 2002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES ("2026/06/15 12:00:00", 0, 13, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 2, 2, 10053, "2026/09/22 11:59:59", -470, "クリア", 135301, 2, 0, 2002);
